import{_ as a,o,c as n,a2 as t}from"./chunks/framework.BTLSZHNB.js";const u=JSON.parse('{"title":"Host API v1alpha3","description":"","frontmatter":{},"headers":[],"relativePath":"spec/host-api/v1alpha3.md","filePath":"spec/host-api/v1alpha3.md"}'),s={name:"spec/host-api/v1alpha3.md"};function i(r,e,c,d,p,l){return o(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="host-api-v1alpha3" tabindex="-1">Host API v1alpha3 <a class="header-anchor" href="#host-api-v1alpha3" aria-label="Permalink to &quot;Host API v1alpha3&quot;">​</a></h1><p><code>forms.takoform.com/v1alpha3</code> is the current Host API lane (<a href="./../decisions/0013-v1alpha3-lane-ships-in-provider-v2-1.html">decision 0013</a>). It carries namespaced FormRef groups, UID/generation/revision resource identity, long-running Operations, content-addressed artifact upload, and Host Support Profiles. The retained v1alpha2 contract in <a href="./"><code>README.md</code></a> continues to govern the frozen provider-v2 lane; rules stated there and not changed here (space identity, I-JSON raw-first decoding, idempotency-key namespacing, replay fingerprinting, same-origin endpoint negotiation) apply to this lane unchanged.</p><p>The wire schema is <a href="/schemas/v1alpha3/host-api-wire.schema.json"><code>../schemas/host-api-wire-v1alpha3.schema.json</code></a>; the machine operation table is <a href="operations-v1alpha3.json"><code>operations-v1alpha3.json</code></a>.</p><h2 id="discovery" tabindex="-1">Discovery <a class="header-anchor" href="#discovery" aria-label="Permalink to &quot;Discovery&quot;">​</a></h2><p><code>GET /.well-known/takoform/v1alpha3</code> returns a document validating against <a href="/schemas/v1alpha3/host-discovery.schema.json"><code>../schemas/host-discovery-v1alpha3.schema.json</code></a>: <code>api_versions</code> is exactly <code>[&quot;forms.takoform.com/v1alpha3&quot;]</code>; the features <code>service_forms</code>, <code>exact_form_ref</code>, <code>optimistic_concurrency</code>, <code>idempotent_lifecycle</code>, <code>operations</code>, <code>artifact_upload</code>, and <code>support_profiles</code> are all required and true; <code>endpoints.api</code> is same-origin with path <code>/apis/forms.takoform.com/v1alpha3</code>. Each lane has its own discovery path; a v1alpha2 client can never select this lane accidentally.</p><h2 id="resource-identity" tabindex="-1">Resource identity <a class="header-anchor" href="#resource-identity" aria-label="Permalink to &quot;Resource identity&quot;">​</a></h2><ul><li><code>metadata.name</code> is the only name; Form desired schemas do not carry a <code>name</code> field.</li><li><code>metadata.uid</code> is host-issued and immutable. Delete followed by re-create of the same name yields a new UID. A client MAY fence any mutation with <code>expectedUid</code>; mismatch fails <code>uid_mismatch</code> (409).</li><li><code>metadata.generation</code> increments only when the portable desired spec changes. Desired-state mutations fence on the expected generation (<code>Takoform-Expected-Generation</code> header or <code>expectedGeneration</code> body field); a stale fence fails <code>generation_conflict</code> (412).</li><li><code>metadata.revision</code> increments whenever the representation — including status, conditions, and outputs — changes. The strong ETag is the quoted revision; <code>If-Match</code> fences on it and a stale value fails <code>revision_conflict</code> (412).</li><li><code>status.observedGeneration</code> names the desired generation the status reflects; <code>status.conditions</code> uses the closed types <code>Ready</code>, <code>Reconciling</code>, <code>Degraded</code>, <code>Drifted</code>, <code>Blocked</code>, <code>Deleting</code> with closed portable reasons and an optional non-portable <code>hostReason</code>.</li><li>The Form semantic identity is the exact FormRef. The package digest used at installation is audit evidence (<code>form.packageDigest</code>, optional in responses); it never enters queries, fences, or state identity, and a host that installed the same FormRef from a different legitimate package MUST read and delete the same resources.</li></ul><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><p>Endpoints under <code>/apis/forms.takoform.com/v1alpha3</code>, keyed by group and kind so one kind name can exist in many groups:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET    {api}/forms?space&amp;group&amp;kind&amp;definitionVersion&amp;schemaDigest</span></span>
<span class="line"><span>GET    {api}/form-definitions/{group}/{kind}?…</span></span>
<span class="line"><span>POST   {api}/resources/validate         diagnostics only, no mutation, no digest</span></span>
<span class="line"><span>POST   {api}/resources/prepare          short-lived prepare digest for one exact spec</span></span>
<span class="line"><span>PUT    {api}/resources/{group}/{kind}/{name}    apply; carries review.prepareDigest</span></span>
<span class="line"><span>GET    {api}/resources/{group}/{kind}/{name}</span></span>
<span class="line"><span>POST   {api}/resources/{group}/{kind}/{name}/import</span></span>
<span class="line"><span>POST   {api}/resources/{group}/{kind}/{name}/observe</span></span>
<span class="line"><span>POST   {api}/resources/{group}/{kind}/{name}/refresh</span></span>
<span class="line"><span>DELETE {api}/resources/{group}/{kind}/{name}</span></span></code></pre></div><p><code>validate</code> reports diagnostics without mutating and without minting a digest; a client MUST NOT describe provider apply-time preparation as &quot;reviewed in plan&quot;. <code>prepare</code> binds the exact spec, identity, and fences to a <code>prepareDigest</code> the way v1alpha2 <code>preview</code> binds a plan digest; substitution after prepare fails <code>invalid_argument</code> before mutation.</p><p>Role rules are wire-enforced: an update to a <code>revision</code>-role resource fails <code>invalid_argument</code>; deleting a bound target fails <code>dependency_in_use</code> (409); a resource protected by policy fails <code>deletion_protected</code> (409).</p><h2 id="long-running-operations" tabindex="-1">Long-running operations <a class="header-anchor" href="#long-running-operations" aria-label="Permalink to &quot;Long-running operations&quot;">​</a></h2><p>Create, update, delete, import, and artifact commit MAY return <code>202 Accepted</code> with an Operation envelope (<a href="/schemas/operations/v1alpha1/operation.schema.json"><code>../schemas/operation-v1alpha1.schema.json</code></a>) instead of the terminal representation:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET  {api}/operations/{id}</span></span>
<span class="line"><span>POST {api}/operations/{id}/cancel</span></span></code></pre></div><p>Clients poll with <code>Retry-After</code> when present, otherwise exponential backoff with full jitter, under an overall deadline. The contract guarantees only that an operation ID is stable, that the host keeps it addressable at <code>GET {api}/operations/{id}</code> while the operation record exists (afterwards the closed outcome is <code>operation_not_found</code>), and that a terminal operation replays its terminal state instead of re-executing. A client can resume across its own restart only if it persists the ID first; no shipped Takoform client persists one today, so a restart during a long operation currently means re-reading the resource, not resuming the operation. A terminal Operation carries exactly one of <code>result</code> or <code>error</code>. Cancel is honored only for safely stoppable operations; an already-terminal operation replays its terminal state. <code>operation_not_found</code> (404) and <code>operation_cancelled</code> (409) are the closed outcomes; <code>deadline_exceeded</code> (504) reports a host-side deadline.</p><h2 id="artifacts" tabindex="-1">Artifacts <a class="header-anchor" href="#artifacts" aria-label="Permalink to &quot;Artifacts&quot;">​</a></h2><p>The content-addressed upload API is <a href="./../artifact-transport/"><code>../artifact-transport/</code></a>. The artifact endpoints share the lane&#39;s auth, idempotency, and error taxonomy.</p><h2 id="support-profiles" tabindex="-1">Support profiles <a class="header-anchor" href="#support-profiles" aria-label="Permalink to &quot;Support profiles&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET {api}/support/forms</span></span>
<span class="line"><span>GET {api}/support/forms/{group}/{kind}/{definitionVersion}</span></span>
<span class="line"><span>GET {api}/support/interfaces/{name}/{version}</span></span>
<span class="line"><span>GET {api}/support/bindings/{name}/{version}</span></span></code></pre></div><p>Responses validate against <a href="/schemas/support/v1alpha1/host-support-profile.schema.json"><code>../schemas/host-support-profile-v1alpha1.schema.json</code></a>. A profile declares supported exact refs, closed capability subsets (<code>supportedEnums</code>), inclusive ranges (<code>supportedRanges</code>), supported binding contracts, and numeric limits. Price, SKU, region, quota, and commercial policy MUST NOT appear; those remain Service Offering data outside this API.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>The closed taxonomy extends v1alpha2 with <code>rate_limited</code> (429), <code>deadline_exceeded</code> (504), <code>operation_cancelled</code> (409), <code>operation_not_found</code> (404), <code>dependency_in_use</code> (409), <code>deletion_protected</code> (409), <code>artifact_missing</code> (404), <code>artifact_invalid</code> (400), <code>unsupported_capability</code> (422), <code>migration_required</code> (409), <code>uid_mismatch</code> (409), <code>revision_conflict</code> (412), and <code>generation_conflict</code> (412). Only <code>resource_busy</code>, <code>backend_unavailable</code>, <code>rate_limited</code>, and <code>deadline_exceeded</code> may be <code>retryable: true</code>; <code>Retry-After</code> is honored when present. The v1alpha2 codes <code>resource_version_conflict</code>, <code>interface_identity_ambiguous</code>, and <code>interface_instance_ambiguous</code> do not exist in this lane: version conflicts split into the revision/generation pair, and the v1alpha2 interface projection is replaced by exact Interface contracts (<a href="./../interface-contract/"><code>../interface-contract/</code></a>).</p>`,23)])])}const m=a(s,[["render",i]]);export{u as __pageData,m as default};
